{"research_date": "2026-09-10", "pairs": [{"pair_id": "conflict_46bc6fc1e332973355241c39", "claim_ids": ["claim_102f27c721dcc1b883db3ac6", "claim_8b8ba680998dbc8d78276f85"], "query_ids": ["q_371"], "claims": [{"claim_id": "claim_102f27c721dcc1b883db3ac6", "quote": "President Donald Trump’s tariffs on imported steel and aluminum have officially gone into effect.", "url": "https://glc-inc.com/2025/03/steel-tariffs-a-new-challenge-for-the-automotive-industry", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "tariffs on imported steel and aluminum", "reported_policy_status": "officially gone into effect"}}, {"claim_id": "claim_8b8ba680998dbc8d78276f85", "quote": "A proposed 25% tariff on imported vehicles could lead to substantial price increases.", "url": "https://glc-inc.com/2025/03/steel-tariffs-a-new-challenge-for-the-automotive-industry", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "25% tariff on imported vehicles", "reported_policy_status": "proposed"}}]}, {"pair_id": "conflict_0b73da2f56d6caa0f8a2680d", "claim_ids": ["claim_03bf4e2c744bcdd1aa90451d", "claim_297a1e56a70df6367a76ad5e"], "query_ids": ["q_372"], "claims": [{"claim_id": "claim_03bf4e2c744bcdd1aa90451d", "quote": "Lithium-ion EV batteries have carried 25% since 2024. Lithium-ion non-EV batteries also carry 25%, but that rate only took effect in 2026", "url": "https://cargotransinc.com/blog/ev-battery-tariff", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "25%", "effective_date": "2024"}}, {"claim_id": "claim_297a1e56a70df6367a76ad5e", "quote": "the Administration said it would increase the tariff rate on lithium-ion batteries for electric vehicles (EVs) from 7.5% to 25% in 2024, and the tariff rate for non-EV lithium-ion batteries from 7.5% to 25% in 2026.", "url": "https://www.energy-storage.news/us-increases-tariffs-on-batteries-from-china-to-25", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "increase the tariff rate on lithium-ion batteries for electric vehicles (EVs) from 7.5% to 25% in 2024, and the tariff rate for non-EV lithium-ion batteries from 7.5% to 25% in 2026", "effective_date": "2024"}}]}, {"pair_id": "conflict_66be33bee04271cb204b7c98", "claim_ids": ["claim_3d373648a4a646c049de273f", "claim_afcc0b4adef4ccae6a11a600"], "query_ids": ["q_372"], "claims": [{"claim_id": "claim_3d373648a4a646c049de273f", "quote": "Lithium-ion non-EV batteries also carry 25%, but that rate only took effect in 2026", "url": "https://cargotransinc.com/blog/ev-battery-tariff", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "25%", "effective_date": "2026"}}, {"claim_id": "claim_afcc0b4adef4ccae6a11a600", "quote": "the tariff rate for non-EV lithium-ion batteries from 7.5% to 25% in 2026.", "url": "https://www.energy-storage.news/us-increases-tariffs-on-batteries-from-china-to-25", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"effective_date": "2026"}}]}, {"pair_id": "conflict_f92ff2650352ce648774be55", "claim_ids": ["claim_21583c0bf4cc88e3b3eefe1e", "claim_cab615026da05794eb000323"], "query_ids": ["q_373"], "claims": [{"claim_id": "claim_21583c0bf4cc88e3b3eefe1e", "quote": "Lithium-ion batteries are classified under HTS 8507.60 with a base duty rate of 3.4%.", "url": "https://ustariffrates.com/products/batteries", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"hts_code": "8507.60", "duty_rate": "3.4%"}}, {"claim_id": "claim_cab615026da05794eb000323", "quote": "The applicable subheading for the rechargeable battery packs of Lithium-ion battery cells will be 8507.60.0020, HTSUS, which provides for Electric storage batteries, including separators therefor, whether or not rectangular; Lithium-ion batteries: Other. The rate of duty will be 3.4 percent ad valorem.", "url": "https://www.customsmobile.com/rulings/docview?doc_id=NY+N286124&highlight=NY+N286124", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"hts_code": "8507.60.0020", "duty_rate": "3.4 percent ad valorem"}}]}, {"pair_id": "conflict_af4575f71cd60061f8d656ff", "claim_ids": ["claim_1ff954c8f70d7307cac143c2", "claim_e8e2fdeb74442707d0209724"], "query_ids": ["q_374"], "claims": [{"claim_id": "claim_1ff954c8f70d7307cac143c2", "quote": "Covered Chinese lithium-ion non-EV batteries are subject to a 25% legacy Section 301 duty, and a new 12.5% Forced-Labor Section 301 duty generally applies to products of China entered on or after July 24, 2026", "url": "https://www.large-battery.com/blog/us-tariff-on-chinese-lithium-ion-batteries", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 301", "duty_rate": "25%", "effective_date": "July 24, 2026"}}, {"claim_id": "claim_e8e2fdeb74442707d0209724", "quote": "The additional Section 301 rate is 25% for covered Chinese lithium-ion non-EV batteries in 2026.", "url": "https://www.large-battery.com/blog/us-tariff-on-chinese-lithium-ion-batteries", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "25%"}}]}, {"pair_id": "conflict_9c211d26b618e752f40073e5", "claim_ids": ["claim_5c3f1d9abacc5c5296ae050d", "claim_f42b10a5c53162d072cc993e"], "query_ids": ["q_374"], "claims": [{"claim_id": "claim_5c3f1d9abacc5c5296ae050d", "quote": "Covered products of China are generally subject to an additional 12.5% Section 301 duty under the forced-labor action effective July 24, 2026, unless a product exemption applies.", "url": "https://www.large-battery.com/blog/us-tariff-on-chinese-lithium-ion-batteries", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "12.5%", "effective_date": "July 24, 2026"}}, {"claim_id": "claim_f42b10a5c53162d072cc993e", "quote": "Following the 2024 four-year review of the China Section 301 actions, the United States scheduled the additional tariff on lithium-ion non-electrical-vehicle batteries from China to increase from 7.5% to 25% in 2026", "url": "https://www.large-battery.com/blog/us-tariff-on-chinese-lithium-ion-batteries", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 301", "duty_rate": "25%", "effective_date": "2026"}}]}, {"pair_id": "conflict_e843077aaea10e1626cf2f97", "claim_ids": ["claim_5c498c96e8c613518049d796", "claim_6d3aac19c25b309a18ace091"], "query_ids": ["q_374"], "claims": [{"claim_id": "claim_5c498c96e8c613518049d796", "quote": "Lithium-ion batteries are classified under HTS 8507.60 with a base duty rate of 3.4%. Section 301 tariffs on Chinese-origin lithium-ion batteries add 25%, bringing the effective rate to 28.4% for Chinese imports.", "url": "https://ustariffrates.com/products/batteries", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 301", "country_of_origin": "Chinese", "duty_rate": "28.4%"}}, {"claim_id": "claim_6d3aac19c25b309a18ace091", "quote": "Yes, EV battery cells and packs from China face Section 301 tariffs of 25% on top of the base 3.4% duty.", "url": "https://ustariffrates.com/products/batteries", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 301", "duty_rate": "25%"}}]}, {"pair_id": "conflict_c0cf2521cd23fb14eba8c6a2", "claim_ids": ["claim_aab67102bd7d0070506e1012", "claim_e8e2fdeb74442707d0209724"], "query_ids": ["q_374"], "claims": [{"claim_id": "claim_aab67102bd7d0070506e1012", "quote": "EV battery cells and packs from China face Section 301 tariffs of 25% on top of the base 3.4% duty. This has accelerated battery production shifts to South Korea, Japan, and domestic US facilities.", "url": "https://ustariffrates.com/products/batteries", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "25%"}}, {"claim_id": "claim_e8e2fdeb74442707d0209724", "quote": "The additional Section 301 rate is 25% for covered Chinese lithium-ion non-EV batteries in 2026.", "url": "https://www.large-battery.com/blog/us-tariff-on-chinese-lithium-ion-batteries", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "25%"}}]}, {"pair_id": "conflict_0b88d05cf518a8dc66a475d3", "claim_ids": ["claim_1ff954c8f70d7307cac143c2", "claim_f42b10a5c53162d072cc993e"], "query_ids": ["q_374"], "claims": [{"claim_id": "claim_1ff954c8f70d7307cac143c2", "quote": "Covered Chinese lithium-ion non-EV batteries are subject to a 25% legacy Section 301 duty, and a new 12.5% Forced-Labor Section 301 duty generally applies to products of China entered on or after July 24, 2026", "url": "https://www.large-battery.com/blog/us-tariff-on-chinese-lithium-ion-batteries", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 301", "duty_rate": "25%", "effective_date": "July 24, 2026"}}, {"claim_id": "claim_f42b10a5c53162d072cc993e", "quote": "Following the 2024 four-year review of the China Section 301 actions, the United States scheduled the additional tariff on lithium-ion non-electrical-vehicle batteries from China to increase from 7.5% to 25% in 2026", "url": "https://www.large-battery.com/blog/us-tariff-on-chinese-lithium-ion-batteries", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 301", "duty_rate": "25%", "effective_date": "2026"}}]}, {"pair_id": "conflict_27f5f7e88201c571edf9d769", "claim_ids": ["claim_13300913193c6f509d0c06c2", "claim_d0feba095dacf738da9f946a"], "query_ids": ["q_375"], "claims": [{"claim_id": "claim_13300913193c6f509d0c06c2", "quote": "Yes, EV battery cells and packs from China face Section 301 tariffs of 25% on top of the base 3.4% duty.", "url": "https://ustariffrates.com/products/batteries", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 301 tariffs", "duty_rate": "25%"}}, {"claim_id": "claim_d0feba095dacf738da9f946a", "quote": "imposing a 100% ad valorem duty on Chinese EV imports and a 25% tariff on lithium-ion battery cells and packs, alongside a 7.5% tariff on graphite and critical minerals.", "url": "https://energy-solutions.co/supply-chain/risk-index/us-section-301-tariffs-on-chinese-evs-and-batteries", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "US Section 301", "duty_rate": "100%"}}]}]}

